const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let S=null,U=null,page='dashboard',sessionSetup=false,filters={},busy=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}).format((n||0)/100);
const qfmt=n=>new Intl.NumberFormat('th-TH',{maximumFractionDigits:3}).format((n||0)/1000);
const nowDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const thaiDate=d=>d?new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeZone:'Asia/Bangkok'}).format(new Date(d+'T12:00:00+07:00')):'—';
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8h18M15 12h6v5h-6z"/>',customers:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 4 5"/>',stock:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5zM3 8l9 5 9-5M12 13v9M7 5l10 6"/>',purchase:'<path d="M3 3h2l3 12h11l2-9H6"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',debt:'<rect x="5" y="3" width="14" height="19" rx="2"/><path d="M9 7h6M9 11h6M9 15h6M9 19h3"/>',report:'<path d="M3 3v18h18M7 16v-5M12 16V7M17 16v-9"/>',trello:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M8 7v10M16 7v6"/>',review:'<path d="M8 3h8l3 3v15H5V3h3zM9 12l2 2 4-4M9 18h6"/>',settings:'<path d="m9 3 6 0 1 4 4 1v7l-4 1-1 5H9l-1-5-4-1V8l4-1z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M12 19V5m-6 6 6-6 6 6"/>',down:'<path d="M12 5v14m-6-6 6 6 6-6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',logout:'<path d="M10 4H4v16h6M14 8l4 4-4 4M8 12h10"/>'};
const icon=k=>`<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.debt}</svg>`;
const titles={dashboard:'ภาพรวมกิจการ',wallet:'รายรับ · รายจ่าย',customers:'ลูกค้าและคอร์สเรียน',stock:'สต๊อกและการประกอบ',purchase:'รายการสั่งซื้อ',debt:'เงินส่วนตัวและหนี้',report:'รายงาน',documents:'ใบเสนอราคา · Invoice',trello:'เชื่อมต่อ Trello',review:'ข้อมูลรอตรวจสอบ',settings:'ตั้งค่าและสำรองข้อมูล',payroll:'เงินเดือนพนักงาน',access:'จัดการสิทธิ์ผู้ใช้งาน'};
const types={opening:'ยอดยกมา',income:'รับเงิน',expense:'จ่ายค่าใช้จ่าย',advance:'เบิกเงินซื้อของ',settlement:'เคลียร์เงินเบิก',advance_return:'คืนเงินเบิก',owner_in:'เจ้าของเติมเงิน',owner_out:'เจ้าของถอนใช้',debt_repay:'คืนเงินต้นหนี้',interest:'จ่ายดอกเบี้ย',reversal:'กลับรายการ'};
const movementTypes={receive:'รับสินค้า',issue:'เบิกใช้',return:'คืนของ',transfer:'โอนที่เก็บ',adjust_in:'ปรับเพิ่ม',adjust_out:'ปรับลด',assembly_in:'ประกอบสำเร็จ',assembly_out:'ใช้ประกอบ'};
const name=(arr,id)=>arr?.find(x=>x.id===id)?.name||'—';
const active=()=>S.entries.filter(e=>!e.reverses&&!S.entries.some(x=>x.reverses===e.id));
const isActive=e=>!e.reverses&&!S.entries.some(x=>x.reverses===e.id);
const paid=id=>active().filter(e=>e.enrollmentId===id).reduce((a,e)=>a+e.amount,0);
const advanceLeft=id=>S.entries.find(e=>e.id===id).amount-active().filter(e=>e.advanceId===id).reduce((a,e)=>a+e.amount,0);
const stock=id=>S.lots.filter(l=>l.productId===id).reduce((a,l)=>a+l.quantity,0);
const owner=()=>U?.role==='owner';
const btn=(label,act,cls='secondary',attrs='')=>act.includes('salary-summary-')?'':U?.role==='viewer'&&!['go','menu','csv','print','close'].includes(act.split(':')[0])?'':`<button class="${cls}" data-act="${act}" ${attrs}>${label}</button>`;
const options=(a,fn=x=>x.name,selected='')=>'<option value="">เลือก…</option>'+a.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(fn(x))}</option>`).join('');
const field=(label,n,type='text',opts={})=>`<label class="${opts.full?'full':''}"><span>${label}${opts.optional?'':' *'}</span>${type==='select'?`<select name="${n}" ${opts.optional?'':'required'}>${opts.options||''}</select>`:type==='textarea'?`<textarea name="${n}" ${opts.optional?'':'required'} maxlength="500">${esc(opts.value||'')}</textarea>`:`<input name="${n}" type="${type}" ${opts.optional?'':'required'} value="${esc(opts.value??(type==='date'?nowDate():''))}" ${opts.extra||''}>`}${opts.help?`<small>${opts.help}</small>`:''}</label>`;
const moneyField=(label,n='amount',opts={})=>field(label,n,'text',{...opts,extra:'inputmode="decimal" pattern="[0-9]+(\\.[0-9]{1,2})?" placeholder="0.00"'});
const qtyField=(label,n='quantity')=>field(label,n,'text',{extra:'inputmode="decimal" pattern="[0-9]+(\\.[0-9]{1,3})?" placeholder="0"'});
const badge=(t,cls='')=>`<span class="badge ${cls}">${esc(t)}</span>`;
const empty=(title,sub,action='')=>`<div class="empty">${icon('debt')}<strong>${title}</strong>${sub}${action}</div>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(url,data){const r=await fetch(url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':U?.csrf||''}:{},body:data?JSON.stringify(data):undefined});const b=await r.json();if(!r.ok)throw new Error(b.error||'ทำรายการไม่สำเร็จ');return b;}
async function reload(){S=await api('/api/state');render();}
async function act(action,payload){return api('/api/action',{action,payload,requestId:crypto.randomUUID()});}
function openModal(title,content,onSubmit,label='บันทึกรายการ',syncAction=null){syncAction ||= {'รับ / เบิก / คืน / โอนสินค้า':'movement','เพิ่มสูตรประกอบ Simulator':'bom','ประกอบ Simulator':'assemble','เพิ่มพนักงาน':'employee','แก้ไขพนักงาน':'employee','สร้างเงินเดือน':'payrollSave','แก้ไขเงินเดือน':'payrollSave','ยืนยันจ่ายเงินเดือน':'payrollPay','ยกเลิกเงินเดือน':'payrollCancel'}[title];if(trelloClientKinds[syncAction])content+=trelloFormFields(syncAction)+integrationFileFields();else syncAction=null;currentSyncForm=null;const d=$('#modal');$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2>${btn('✕','close','ghost','aria-label="ปิด"')}</div><div class="modal-body"><form id="modal-form"><div class="form-grid">${content}</div><div class="error" role="alert"></div><div class="modal-footer">${btn('ยกเลิก','close','secondary')}<button type="submit">${label}</button></div></form></div>`;d.showModal();const form=$('#modal-form');form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(form)));d.close();await reload();toast('บันทึกเรียบร้อย');}catch(err){form.querySelector('.error').textContent=err.message;}finally{busy=false;submit.disabled=false;}};if(syncAction)setupTrelloForm(syncAction);}
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const panel=(title,sub,body,actions='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2><div class="muted">${sub}</div></div>${actions}</div>${body}</section>`;
const metric=(label,value,ico,foot)=>`<div class="metric"><div class="metric-top">${label}<span class="metric-icon">${icon(ico)}</span></div><div class="metric-value"><span class="currency">฿</span>${fmt(value)}</div><div class="metric-foot">${foot}</div></div>`;
function authView(setup){sessionSetup=setup;$('#app').innerHTML=`<div class="auth-screen"><section class="auth-brand"><div class="logo"><div class="logo-symbol">M</div><div><strong>MY TECH</strong><small>BUSINESS WORKSPACE</small></div></div><div class="tagline">มองเห็นทุกบาท · จัดการทุกชิ้น</div><h1>ดูแลกิจการให้เป็นระบบ<br>เริ่มจากที่เดียว</h1><p>รายรับคอร์สเรียน ค่าใช้จ่าย เงินเบิก และสต๊อกอุปกรณ์<br>เชื่อมงานของคุณเข้ากับ Trello อย่างเป็นระเบียบ</p><div class="dots"><i></i><i></i><i></i></div></section><section class="auth-form"><span class="local-tag">${icon('shield')} ใช้งานบนเครื่องนี้ · ยังไม่เผยแพร่ออนไลน์</span><div class="eyebrow" style="margin-top:25px">WELCOME TO MY TECH</div><h2>${setup?'เริ่มต้นพื้นที่ทำงานของคุณ':'ยินดีต้อนรับกลับ'}</h2><p class="muted">${setup?'ตั้งบัญชีเจ้าของครั้งแรก ข้อมูลจะถูกเก็บในฐานข้อมูลบนเครื่องนี้':'เข้าสู่ระบบเพื่อดูแลบัญชีและสต๊อกของกิจการ'}</p><form id="auth-form">${setup?field('ชื่อที่แสดง','name','text',{value:'ปิ๊ก',extra:'maxlength="100" autocomplete="name"'}):''}${field('ชื่อผู้ใช้','username','text',{extra:'autocomplete="username" maxlength="60"'})}${field('รหัสผ่าน','password','password',{extra:`minlength="10" maxlength="200" autocomplete="${setup?'new-password':'current-password'}"`,help:'อย่างน้อย 10 ตัวอักษร'})}<div class="error" role="alert"></div><button type="submit">${setup?'สร้างบัญชีเจ้าของและเริ่มใช้งาน':'เข้าสู่ระบบ'} →</button></form><p class="muted" style="margin-top:24px;font-size:10px">ข้อมูลเก่าจะไม่ถูกลงบัญชีอัตโนมัติ คุณตรวจสอบก่อนนำมาใช้ได้<br>ข้อมูลตัวเลขยังว่าง จนกว่าจะเพิ่มรายการที่ยืนยันแล้ว</p></section></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button');button.disabled=true;try{const b=await api(setup?'/api/setup':'/api/login',Object.fromEntries(new FormData(f)));U=b.user;await reload();}catch(err){f.querySelector('.error').textContent=err.message;}finally{button.disabled=false;}};}
function render(){const count=S.pending.filter(x=>x.status==='pending').length;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="logo"><div class="logo-symbol">M</div><div><strong>MY TECH</strong><small>BUSINESS WORKSPACE</small></div></div><div class="nav-label">พื้นที่ทำงาน</div><nav class="nav">${['dashboard','access','wallet','payroll','signature',...Object.keys(titles).filter(k=>!['dashboard','access','wallet','payroll','signature'].includes(k))].filter(k=>owner()||!['debt','review','settings','trello','payroll','signature'].includes(k)).map(k=>`<button data-page="${k}" class="${page===k?'active':''}">${icon(k)}${titles[k]}${k==='review'&&count?`<span class="count">${count}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="trello-mini">${icon('trello')} <strong>My Tech update</strong><span class="dot"></span>${S.trello.connected?'เชื่อมต่อแล้ว · อัปเดตด้วยปุ่มรีเฟรช':'รอตั้งค่าการเชื่อมต่อเว็บ'}</div><div class="profile"><div class="avatar">${esc(U.name.slice(0,1))}</div><div><strong>${esc(U.name)}</strong><small>${owner()?'เจ้าของกิจการ':U.role==='staff'?'ผู้แก้ไข':'ดูอย่างเดียว'}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">${btn(icon('menu'),'menu','mobile-menu','aria-label="เมนู"')}พื้นที่ทำงาน <span>/ &nbsp;${titles[page]}</span></div><div class="top-actions">${accessTopLink()}<span class="date-label">${thaiDate(nowDate())}</span><span class="local-tag"><span class="dot"></span> ฐานข้อมูลกลาง</span>${U.id==='visitor'?'<a class="signin-link" target="_top" href="/signin-with-chatgpt?return_to=%2F">เข้าสู่ระบบ</a>':'<a class="signin-link" target="_top" href="/signout-with-chatgpt?return_to=%2F">ออกจากระบบ</a>'}</div></header><div class="content"><div class="pagehead"><div><div class="eyebrow">MY TECH / ${page.toUpperCase()}</div><h1>${titles[page]}</h1><div class="muted">${page==='dashboard'?'ทุกความเคลื่อนไหวของกิจการ ในมุมมองเดียว':'จัดการข้อมูลที่ยืนยันแล้ว พร้อมเก็บประวัติทุกรายการ'}</div></div><div class="actions">${pageActions()}</div></div><div id="page-body">${views[page]()}</div><div class="footer"><span>MY TECH • บัญชี สต๊อก และเงินเดือน</span><span>ข้อมูลจริงแยกจากรายการรอตรวจสอบ · เวลาประเทศไทย · รุ่นออนไลน์ 2.0</span></div></div></main></div>`;bindFilters();}
function pageActions(){if(page==='signature')return owner()?btn('เขียน / แก้ไขลายเซ็น','signature',''):'';if(page==='payroll')return btn('เพิ่มพนักงาน','employee','')+btn('สร้างเงินเดือน','payroll:new')+btn('ส่งออก CSV','payrollcsv');if(page==='access')return owner()?btn('เพิ่มอีเมลผู้แก้ไข','member',''):'';if(page==='dashboard')return btn(icon('plus')+' รับเงิน','entry:income','')+btn('จ่ายเงิน','entry:expense');if(page==='documents')return btn('ออกใบเสนอราคา','newdoc:quote','')+btn('ออก Invoice','newdoc:invoice')+(owner()?btn('เขียน / แก้ไขลายเซ็น','signature','secondary'):'');if(page==='wallet')return btn('รับเงิน','entry:income','')+btn('จ่าย / เบิกเงิน','entry:expense');if(page==='customers')return btn('เพิ่มลูกค้า','customer','')+btn('เพิ่มคอร์ส','course')+btn('ลงทะเบียน','enroll');if(page==='stock')return btn('เพิ่มสินค้า','product','')+btn('รับ / เบิก / คืน','movement')+btn('ประกอบ Simulator','assemble');if(page==='purchase')return btn('เพิ่มใบสั่งซื้อ','purchase','');if(page==='debt')return btn('เพิ่มหนี้','debt','')+btn('ชำระหนี้','entry:debt_repay');if(page==='review')return !S.pending.length?btn('นำเข้าข้อมูลจากแชต','importHistory',''):'';if(page==='report')return btn('ส่งออก CSV','csv','')+btn('พิมพ์ / บันทึก PDF','print');return '';}
const views={dashboard:dashboardView,wallet:walletView,customers:customerView,stock:stockView,purchase:purchaseView,debt:debtView,report:reportView,trello:trelloView,review:reviewView,settings:settingsView,documents:documentsView,payroll:()=>payrollView(),access:()=>accessView()};
function dashboardView(){const t=S.summary;const unsetup=S.accounts.length===0;const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setMonth(d.getMonth()-5+i);return {ym:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),label:new Intl.DateTimeFormat('th',{month:'short'}).format(d)};});const sums=months.map(m=>{const a=active().filter(e=>e.date.startsWith(m.ym)&&S.accounts.find(a=>a.id===e.accountId)?.scope==='business');return {...m,in:a.reduce((t,e)=>t+Math.max(0,e.cash),0),out:a.reduce((t,e)=>t+Math.max(0,-e.cash),0)};});const max=Math.max(1,...sums.flatMap(x=>[x.in,x.out]));return `${accessDashboardCard()}${payrollDashboardCard()}${unsetup?`<section class="hero"><div><small>พร้อมจัดระเบียบกิจการของคุณ</small><h2>เริ่มต้นด้วยบัญชีเงินสดหรือธนาคาร</h2><p>เพิ่มบัญชีและยอดเริ่มต้น แล้วบันทึกรายรับรายจ่ายได้ทันที ข้อมูลจากแชตเก่าจะเก็บแยกไว้ให้คุณตรวจสอบก่อน</p></div>${btn('ตั้งค่าบัญชีแรก →','account','')}</section>`:`<section class="hero"><div><small>พื้นที่ทำงานของ ${esc(U.name)}</small><h2>เห็นเงินเข้า รู้เงินออก ติดตามของได้</h2><p>บันทึกจากหลักฐานจริง ยอดเงินเบิกและค่าใช้จ่ายแยกจากกัน เพื่อให้ติดตามเงินทุกส่วนได้ชัดเจน</p></div>${btn('ดูรายงาน →','go:report','')}</section>`}<div class="metrics">${metric('รับเงินจริงของกิจการ',t.income,'arrow','ยอดรับเงินสะสมที่บันทึกแล้ว')}${metric('ค่าใช้จ่ายที่บันทึก',t.expense,'down','รวมใบเสร็จเคลียร์เบิก · ไม่บวกเงินเบิกซ้ำ')}${metric('ค้างรับจากผู้เรียน',t.receivable,'customers','คำนวณจากการลงทะเบียนที่ยืนยันแล้ว')}${metric('มูลค่าสต๊อกคงเหลือ',t.stockValue,'stock','ต้นทุนเฉลี่ยถ่วงน้ำหนัก แยกตามที่เก็บ')}</div><div class="dashboard-grid"><div>${panel('เงินเข้าและเงินออก','ความเคลื่อนไหวเงินสดของกิจการ · 6 เดือนล่าสุด',`<div class="chart">${sums.map(x=>`<div class="chart-bars" title="${x.label} รับ ${fmt(x.in)} / จ่าย ${fmt(x.out)}"><i style="height:${Math.max(1,x.in/max*100)}%"></i><i style="height:${Math.max(1,x.out/max*100)}%"></i></div>`).join('')}</div><div class="chart-labels">${sums.map(x=>`<span>${x.label}</span>`).join('')}</div><div class="legend"><span><i></i>เงินเข้า</span><span><i></i>เงินออก</span></div>${!S.entries.length?'<div class="muted" style="text-align:center;margin-top:18px">ยังไม่มีรายการบันทึก กราฟจะแสดงเมื่อเริ่มใช้งาน</div>':''}`)}${panel('รายการล่าสุด','รับเงิน จ่ายเงิน และเคลียร์เงินเบิก',S.entries.length?entryTable(S.entries.slice(-5).reverse()):empty('ยังไม่มีรายการรับ–จ่าย','เริ่มจากเพิ่มบัญชี แล้วบันทึกเงินจากหลักฐานจริง',btn('เพิ่มบัญชี','account','small secondary')),btn('ดูทั้งหมด →','go:wallet','ghost'))}</div><div>${panel('เงินในบัญชี','ยอดตามรายการที่บันทึก · ตรวจเทียบยอดจริงเสมอ',t.accounts.length?t.accounts.map(a=>`<div class="account-row"><span>${icon('wallet')}</span><div><strong>${esc(a.name)}</strong><small>${a.scope==='personal'?'ส่วนตัว':'กิจการ'} ${a.openingSet?'':'· ยังไม่ตั้งยอดยกมา'}</small></div><b>฿${fmt(a.balance)}</b></div>`).join(''):empty('เพิ่มบัญชีเงินของคุณ','แยกเงินกิจการและเงินส่วนตัวให้ชัดเจน',btn('เพิ่มบัญชี','account','small secondary')))}${panel('ทำรายการอย่างรวดเร็ว','เลือกสิ่งที่คุณต้องการบันทึก',`<div class="quick-grid">${btn(icon('arrow')+'รับเงิน','entry:income')}${btn(icon('down')+'จ่ายเงิน','entry:expense')}${btn(icon('stock')+'รับสินค้า','movement')}${btn(icon('purchase')+'เบิกซื้อของ','entry:advance')}</div>`)}<div class="notice"><strong>เงินเบิกยังไม่เคลียร์ ฿${fmt(t.advance)}</strong>บันทึกใบเสร็จหรือเงินคืน เพื่อเคลียร์ยอดเบิกแต่ละครั้ง</div>${t.pending?`<div class="notice info"><strong>ข้อมูลจากแชตรอตรวจสอบ ${t.pending} รายการ</strong>ยังไม่รวมในยอดบัญชี ${btn('ตรวจข้อมูล →','go:review','ghost')}</div>`:''}</div></div>`;}
function entryTable(entries){return table(['วันที่ / รายการ','บัญชี','คอร์ส / โครงการ','จำนวนเงิน','หลักฐาน / การจัดการ'],entries.map(e=>`<tr><td>${thaiDate(e.date)}<br><span class="muted">${types[e.type]||e.type} · ${esc(e.note)}</span>${!isActive(e)?'<br>'+badge(e.reverses?'กลับรายการ':'ถูกกลับรายการแล้ว','gray'):''}</td><td>${esc(name(S.accounts,e.accountId))}</td><td>${esc(e.project||'—')}</td><td class="num ${e.cash<0?'negative':'positive'}">${e.type==='settlement'?'เคลียร์ ':e.cash<0?'−':'+'}฿${fmt(e.amount)}</td><td><div class="actions">${entryTrelloActions(e)}${btn('รายละเอียด','detail:'+e.id,'small secondary')}${btn('แนบไฟล์','attach:'+e.id,'small secondary')}${owner()&&isActive(e)&&e.type!=='opening'?btn('กลับรายการ','reverse:'+e.id,'small danger'):''}</div></td></tr>`));}
function filterToolbar(project=true){const projects=[...new Set([...S.entries,...S.movements].map(e=>e.project).filter(Boolean))];return `<div class="toolbar"><input id="search" aria-label="ค้นหารายการ" placeholder="ค้นหารายการ…" value="${esc(filters.search||'')}"><input id="from" type="date" aria-label="ตั้งแต่วันที่" value="${esc(filters.from||'')}"><input id="to" type="date" aria-label="ถึงวันที่" value="${esc(filters.to||'')}">${project?`<select id="project" aria-label="คอร์สหรือโครงการ"><option value="">ทุกคอร์ส / โครงการ</option>${projects.map(p=>`<option ${p===filters.project?'selected':''}>${esc(p)}</option>`).join('')}</select>`:''}${btn('ล้างตัวกรอง','clearfilters','small secondary')}</div>`;}
function filtered(a){return a.filter(x=>(!filters.from||x.date>=filters.from)&&(!filters.to||x.date<=filters.to)&&(!filters.project||x.project===filters.project)&&(!filters.search||JSON.stringify(x).toLowerCase().includes(filters.search.toLowerCase())));}
function walletView(){const a=filtered(S.entries).reverse();return `${filterToolbar()}<div class="notice info">รายการเงินเบิกเป็นเงินจ่ายออก แต่จะนับเป็นค่าใช้จ่ายเมื่อมีใบเสร็จเคลียร์เบิก ยอดยกมาและเงินเจ้าของเติมไม่ใช่รายได้จากลูกค้า</div>${panel('บันทึกรับ–จ่าย',`${a.length} รายการ · บันทึกแล้วเก็บประวัติด้วยการกลับรายการ`,a.length?entryTable(a):empty('ยังไม่มีรายการในช่วงนี้','เพิ่มรายการ หรือเปลี่ยนตัวกรอง'))}${panel('เงินเบิกรอเคลียร์','นำใบเสร็จมาเคลียร์ หรือบันทึกคืนเงินเหลือ',active().filter(e=>e.type==='advance'&&advanceLeft(e.id)>0).map(e=>`<div class="account-row"><div><strong>${esc(e.note)}</strong><small>${thaiDate(e.date)} · ${esc(name(S.accounts,e.accountId))}</small></div><b>฿${fmt(advanceLeft(e.id))}</b>${btn('เคลียร์เบิก','settle:'+e.id,'small secondary')}</div>`).join('')||empty('ไม่มีเงินเบิกค้าง','เมื่อเบิกเงิน รายการจะปรากฏที่นี่'))}`;}
function customerView(){return `${panel('ทะเบียนผู้เรียน','มัดจำและชำระหลายงวดได้ · การเข้าร่วมคอร์สอื่นไม่สร้างรายรับซ้ำ',S.enrollments.length?table(['ผู้เรียน','คอร์ส / รุ่น','ราคาที่ตกลง','รับแล้ว','คงเหลือ','จัดการ'],S.enrollments.map(e=>{const c=S.courses.find(c=>c.id===e.courseId);return `<tr><td>${esc(name(S.customers,e.customerId))}</td><td>${esc(c.name)}<br><span class="muted">${esc(c.cohort)}</span></td><td class="num">${fmt(e.price)}</td><td class="num positive">${fmt(paid(e.id))}</td><td class="num">${fmt(e.price-paid(e.id))}</td><td><div class="actions">${btn('รับชำระ','pay:'+e.id,'small secondary')}${btn('เข้าร่วมคอร์ส','attend:'+e.id,'small secondary')}${btn('Trello','link:enrollment:'+e.id,'small secondary')}</div></td></tr>`;})):empty('ยังไม่มีผู้ลงทะเบียน','เพิ่มลูกค้าและคอร์ส แล้วจึงลงทะเบียน'))}${panel('รายชื่อลูกค้า','เก็บช่องทางติดต่อและเชื่อมการ์ด Trello',S.customers.length?table(['ชื่อ','โทรศัพท์','LINE','หมายเหตุ','Trello'],S.customers.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone||'—')}</td><td>${esc(c.line||'—')}</td><td class="wrap">${esc(c.note)}</td><td>${linkView('customer',c.id)}</td></tr>`)):empty('ยังไม่มีลูกค้า','เริ่มเพิ่มจากข้อมูลที่ตรวจสอบแล้ว'))}${panel('คอร์สและรุ่นเรียน','ราคามาตรฐาน · เปลี่ยนราคาที่ตกลงได้ตอนลงทะเบียน',S.courses.length?table(['คอร์ส','รุ่น','ราคามาตรฐาน'],S.courses.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.cohort)}</td><td class="num">${fmt(c.price)}</td></tr>`)):empty('ยังไม่มีคอร์ส','เพิ่มคอร์สเรียนของคุณ'))}${S.attendance.length?panel('ประวัติเข้าร่วมคอร์ส','ใช้การลงทะเบียนเดิม ไม่สร้างยอดขายใหม่',table(['วันที่','ลูกค้า','คอร์สที่เข้าร่วม'],S.attendance.map(a=>`<tr><td>${thaiDate(a.date)}</td><td>${esc(name(S.customers,S.enrollments.find(e=>e.id===a.enrollmentId)?.customerId))}</td><td>${esc(name(S.courses,a.courseId))}</td></tr>`))):''}`;}
function linkView(kind,id){const l=S.links.find(x=>x.kind===kind&&x.recordId===id);return `${l?`<a href="${esc(l.url)}" target="_blank" rel="noreferrer">เปิดการ์ด ↗</a> `:''}${btn(l?'ตั้งค่าลิงก์':'เชื่อมการ์ด','link:'+kind+':'+id,'small secondary')}`;}
function stockView(){const products=S.products.filter(p=>!filters.search||[p.name,p.sku].join(' ').toLowerCase().includes(filters.search.toLowerCase()));return `<div class="toolbar"><input id="search" placeholder="ค้นหาชื่อหรือรหัสสินค้า" value="${esc(filters.search||'')}">${btn('เพิ่มสูตรประกอบ','bom')}${btn('บันทึกความเคลื่อนไหว','movement')}</div><div class="notice info">ต้นทุนใช้ค่าเฉลี่ยถ่วงน้ำหนักแยกตามที่เก็บ รับของเข้าสต๊อกไม่ทำให้เงินจ่ายออกอัตโนมัติ ต้องบันทึกชำระใบสั่งซื้อแยกกัน</div>${panel('สินค้าคงเหลือ','วัสดุ เครื่องมือ และของสำเร็จรูป',products.length?table(['สินค้า','ประเภท','คงเหลือ','มูลค่าต้นทุน','ที่เก็บ / สถานะ','จัดการ'],products.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><span class="muted">${esc(p.sku)}</span></td><td>${{material:'วัสดุ / อะไหล่',tool:'เครื่องมือใช้ซ้ำ',finished:'ของสำเร็จรูป'}[p.kind]}</td><td class="num">${qfmt(stock(p.id))} ${esc(p.unit)}</td><td class="num">฿${fmt(S.lots.filter(l=>l.productId===p.id).reduce((a,l)=>a+l.value,0))}</td><td class="wrap">${S.lots.filter(l=>l.productId===p.id&&l.quantity).map(l=>esc(l.location)+': '+qfmt(l.quantity)).join('<br>')||'—'}<br>${stock(p.id)<=p.min?badge('ถึงจุดสั่งซื้อ','warn'):badge('เพียงพอ')}</td><td>${linkView('product',p.id)}</td></tr>`)):empty('ยังไม่มีสินค้า','เพิ่มสินค้าก่อนรับเข้า แล้วจำนวนจะแสดงตามของที่รับจริง'))}${panel('ประวัติความเคลื่อนไหว','แสดงต้นทุนที่โอนไปกับสินค้า · คืนของโดยอ้างอิงใบเบิกเดิม',S.movements.length?table(['วันที่','สินค้า','ประเภท','จำนวน','ต้นทุน','ที่เก็บ / โครงการ'],S.movements.slice().reverse().map(m=>`<tr><td>${thaiDate(m.date)}</td><td>${esc(name(S.products,m.productId))}</td><td>${movementTypes[m.type]}</td><td class="num">${qfmt(m.quantity)}</td><td class="num">${fmt(m.value)}</td><td class="wrap">${esc(m.location)}${m.destination?' → '+esc(m.destination):''}<br><span class="muted">${esc(m.project||m.note)}</span></td></tr>`)):empty('ยังไม่มีความเคลื่อนไหว','สั่งซื้อยังไม่เพิ่มสต๊อก จนกว่าจะบันทึกรับสินค้า'))}${panel('สูตรประกอบ','ต้นทุนชิ้นส่วนจะย้ายไปเป็นต้นทุนของสำเร็จรูป',S.boms.map(b=>`<div class="account-row"><div><strong>${esc(name(S.products,b.productId))}</strong><small>${b.parts.map(p=>esc(name(S.products,p.productId))+' × '+qfmt(p.quantity)).join(' · ')}</small></div>${btn('ประกอบ','assemble:'+b.id,'small secondary')}</div>`).join('')||empty('ยังไม่มีสูตรประกอบ','เพิ่มสินค้าประเภทของสำเร็จรูป แล้วกำหนดชิ้นส่วน'))}`;}
function purchaseView(){return panel('ใบสั่งซื้อและการรับของ','สั่งซื้อ รับของ และชำระเงินเป็นคนละขั้นตอน เพื่อไม่บันทึกซ้ำ',S.purchases.length?table(['วันที่ / ผู้ขาย','สินค้า','สั่ง / รับแล้ว','ยอดรวม / ค้างจ่าย','สถานะ','จัดการ'],S.purchases.slice().reverse().map(p=>{const pay=active().filter(e=>e.purchaseId===p.id).reduce((a,e)=>a+e.amount,0);return `<tr><td>${thaiDate(p.date)}<br><span class="muted">${esc(p.vendor)}</span></td><td>${esc(name(S.products,p.productId))}</td><td>${qfmt(p.quantity)} / ${qfmt(p.received)}</td><td class="num">฿${fmt(p.total)}<br><span class="muted">ค้าง ฿${fmt(p.total-pay)}</span></td><td>${badge(p.received===p.quantity?'รับครบแล้ว':p.received?'รับบางส่วน':'รอรับ',p.received===p.quantity?'':'warn')}</td><td><div class="actions">${btn('รับของ','receive:'+p.id,'small secondary')}${btn('จ่ายเงิน','purchasepay:'+p.id,'small secondary')}${btn('แนบไฟล์','attach:'+p.id,'small secondary')}${btn('Trello','link:purchase:'+p.id,'small secondary')}</div></td></tr>`;})):empty('ยังไม่มีใบสั่งซื้อ','เพิ่มสินค้า แล้วบันทึกสั่งซื้อจากผู้ขาย'))}
function debtView(){return `<div class="notice">หนี้ส่วนตัวแยกจากกิจการ ตั้งยอดหนี้ไม่ทำให้เกิดเงินจ่ายออก เงินคืนต้นหนี้และดอกเบี้ยบันทึกคนละรายการ</div>${panel('หนี้และประวัติชำระ','ยอดประมาณจะแสดงป้ายกำกับเสมอ',S.debts.length?table(['เจ้าหนี้','ประเภท','ยอดตั้งต้น','ชำระเงินต้นแล้ว','คงเหลือ','หมายเหตุ'],S.debts.map(d=>{const p=active().filter(e=>e.type==='debt_repay'&&e.debtId===d.id).reduce((a,e)=>a+e.amount,0);return `<tr><td>${esc(d.name)} ${d.estimated?badge('ประมาณ','warn'):''}</td><td>${d.scope==='personal'?'ส่วนตัวปิ๊ก':'กิจการ'}</td><td class="num">${fmt(d.amount)}</td><td class="num">${fmt(p)}</td><td class="num">${fmt(d.amount-p)}</td><td class="wrap">${esc(d.note)}<br>${d.due?thaiDate(d.due):''}</td></tr>`;})):empty('ยังไม่มีหนี้ที่ยืนยัน','ข้อมูลหนี้พี่หนุ่มจากแชตอยู่ในรายการรอตรวจสอบ'))}${panel('บัญชีเงินส่วนตัว','เงินส่วนตัวไม่รวมรายรับและรายจ่ายของกิจการ',S.summary.accounts.filter(a=>a.scope==='personal').map(a=>`<div class="account-row"><strong>${esc(a.name)}</strong><b>฿${fmt(a.balance)}</b></div>`).join('')||empty('ยังไม่มีบัญชีส่วนตัว','เพิ่มบัญชีเพื่อบันทึกเงินส่วนตัว',btn('เพิ่มบัญชี','account','small secondary')))}`;}
function reportView(){const entries=filtered(active()),biz=entries.filter(e=>S.accounts.find(a=>a.id===e.accountId)?.scope==='business');const total=t=>biz.filter(e=>t.includes(e.type)).reduce((a,e)=>a+e.amount,0);const movements=filtered(S.movements);const costs={};for(const m of movements){if(m.project&&S.products.find(p=>p.id===m.productId)?.kind!=='tool'&&['issue','return'].includes(m.type))costs[m.project]=(costs[m.project]||0)+(m.type==='return'?-m.value:m.value);}return `${filterToolbar()}<div class="report-kpis">${metric('รับเงินจริงตามตัวกรอง',total(['income']),'arrow','ไม่รวมยอดยกมาและเงินเจ้าของ')}${metric('รายจ่ายตามหลักฐาน',total(['expense','settlement']),'down','ไม่รวมเงินเบิกซ้ำ')}${metric('เงินเบิกรอเคลียร์ทั้งหมด',S.summary.advance,'wallet','ไม่เปลี่ยนตามช่วงวันที่')}</div><div class="notice">รายงานนี้แสดงกระแสเงินและต้นทุนที่บันทึก ยังไม่ใช่รายงานกำไรตามเกณฑ์คงค้าง ค่าวัสดุที่ซื้อกับต้นทุนของที่เบิกเป็นคนละมุมมอง ห้ามนำมาบวกเป็นค่าใช้จ่ายซ้ำ</div>${panel('ต้นทุนวัสดุที่ใช้ในคอร์ส / โครงการ','แยกดูจากเงินซื้อของ · เครื่องมือใช้ซ้ำไม่ถูกนับเป็นวัสดุใช้หมด',Object.keys(costs).length?table(['โครงการ','ต้นทุนเบิกสุทธิหลังคืน'],Object.entries(costs).map(([k,v])=>`<tr><td>${esc(k)}</td><td class="num">฿${fmt(v)}</td></tr>`)):empty('ยังไม่มีต้นทุนเบิกตามโครงการ','ระบุคอร์สหรือโครงการตอนเบิกของ'))}${panel('รายการรับ–จ่ายตามตัวกรอง',`${entries.length} รายการ`,entries.length?entryTable(entries):empty('ไม่พบรายการ','เปลี่ยนช่วงวันที่หรือเริ่มบันทึกข้อมูล'))}`;}
function trelloView(){return `<section class="hero"><div><small>WORK CONNECTED</small><h2>My Tech update</h2><p>ติดตามงานบน Trello และเก็บบัญชีไว้ในระบบนี้ การเปลี่ยนสถานะการ์ดจะไม่เปลี่ยนยอดเงินหรือจำนวนสินค้า</p></div><a href="${esc(S.trello.boardUrl)}" target="_blank" rel="noreferrer"><button>เปิดบอร์ด ↗</button></a></section>${panel('สถานะการเชื่อมเว็บ',S.trello.connected?'รีเฟรชล่าสุด '+new Date(S.trello.lastSync).toLocaleString('th-TH'):'เครื่องมือ Trello ในแชตกับการเชื่อมเว็บแอปเป็นคนละสิทธิ์',`<p>${badge(S.trello.connected?'เชื่อมต่อและอ่านข้อมูลสำเร็จ':'ยังไม่ได้เชื่อมเว็บแอป',S.trello.connected?'':'warn')}</p><p class="muted">ตั้ง API Key และ Token ในหน้าตั้งค่าเว็บครั้งแรก รหัสลับเก็บฝั่งเครื่อง ไม่ส่งกลับไปแสดงในหน้าเว็บ หลังตั้งค่าให้กดรีเฟรชเพื่อทดสอบสิทธิ์จริง</p><div class="actions">${btn('ตั้งค่าการเชื่อมต่อ','trelloconfig','')}${btn('รีเฟรชจาก Trello','trellorefresh')}</div><div class="notice info">ลิงก์กลับจากการ์ดใช้ที่อยู่บนเครื่องนี้ เมื่อเปิดจากอุปกรณ์อื่นจะยังเข้าไม่ได้จนกว่าจะนำระบบขึ้นออนไลน์ การอ่าน Trello ไม่ได้นำรายการมาลงบัญชีโดยอัตโนมัติ</div>`)}${S.trello.connected?panel('การ์ดจากบอร์ด','ข้อมูลจากการรีเฟรชครั้งล่าสุด · อ่านอย่างเดียวในมุมมองนี้',S.trello.cards.length?table(['การ์ด','ลิสต์','ลิงก์'],S.trello.cards.map(c=>`<tr><td class="wrap">${esc(c.name)}</td><td>${esc(name(S.trello.lists,c.listId))}</td><td><a href="${esc(c.url)}" target="_blank" rel="noreferrer">เปิดการ์ด ↗</a></td></tr>`)):empty('ไม่มีการ์ดเปิดอยู่','กดรีเฟรชเพื่ออ่านใหม่')):''}${panel('วิธีเชื่อมรายการ','ใช้ปุ่ม Trello ในหน้าลูกค้า การลงทะเบียน สินค้า หรือใบสั่งซื้อ','<p class="muted">เชื่อมลิงก์การ์ดเดิมได้ทันที หรือเมื่อเชื่อมเว็บแล้วให้เลือกสร้าง/อัปเดตการ์ด ระบบตรวจรหัสอ้างอิงก่อนสร้างเพื่อหลีกเลี่ยงการ์ดซ้ำ หากการเขียนหมดเวลา ให้รีเฟรชตรวจผลก่อนกดอีกครั้ง</p>')}`;}
function reviewView(){return `<div class="notice"><strong>รายการเหล่านี้ยังไม่รวมในยอดเงินจริงและสต๊อก</strong>ตรวจหลักฐานก่อน แล้วสร้างรายการจริงด้วยวันที่ บัญชี และยอดที่ยืนยันได้ การทำเครื่องหมายตรวจแล้วเพียงบันทึกสถานะ ไม่ลงบัญชีให้อัตโนมัติ</div>${S.pending.length?`<div class="grid2">${S.pending.map(x=>`<article class="pending-card"><div class="actions" style="justify-content:space-between"><h3>${esc(x.title)}</h3>${badge(x.status==='pending'?'รอตรวจสอบ':x.status==='reviewed'?'ตรวจแล้ว':'ไม่นำมาใช้',x.status==='pending'?'warn':'gray')}</div>${x.amount!==null?`<div class="pending-value">฿${fmt(x.amount)}</div>`:''}<p>${esc(x.note)}</p>${x.reviewNote?`<p>ผลตรวจ: ${esc(x.reviewNote)}</p>`:''}${btn('บันทึกผลตรวจ','review:'+x.id,'small secondary')}</article>`).join('')}</div>`:empty('พร้อมนำข้อมูลจากแชตมาให้ตรวจ','มีรายการประวัติ 9 รายการ โดยจะไม่เพิ่มยอดเงินจริงอัตโนมัติ',btn('นำเข้าข้อมูลจากแชต','importHistory','small secondary'))}`;}
function settingsView(){return `${panel('ข้อมูลกิจการสำหรับเอกสาร','ข้อมูลจะถูกเก็บเป็นสำเนา ณ วันที่ออกใบเสนอราคา / Invoice',`<p class="muted">${esc(S.company.name)}<br>${esc(S.company.address||'ยังไม่ได้ใส่ที่อยู่')}<br>${esc(S.company.phone||'')}</p>${btn('แก้ไขข้อมูลกิจการ','company')}`)}${panel('บัญชีเงินสดและธนาคาร','ตั้งยอดยกมาของแต่ละบัญชี ก่อนบันทึกเงินจ่าย',S.summary.accounts.map(a=>`<div class="account-row"><div><strong>${esc(a.name)}</strong><small>${a.scope==='business'?'กิจการ':'ส่วนตัว'} · ${a.openingSet?'ตั้งยอดยกมาแล้ว':'ยังไม่ตั้งยอดยกมา'}</small></div><b>฿${fmt(a.balance)}</b>${!a.openingSet?btn('ตั้งยอดยกมา','opening:'+a.id,'small secondary'):''}</div>`).join('')+`<div class="actions" style="margin-top:15px">${btn('เพิ่มบัญชี','account')}</div>`)}${panel('สำรองและกู้คืนข้อมูล','สำรองรายการ หลักฐาน และประวัติ · ไม่รวมรหัสผ่านหรือรหัสลับ Trello',`<div class="actions"><a href="/api/backup" download><button>ดาวน์โหลดไฟล์สำรอง</button></a>${btn('กู้คืนจากไฟล์สำรอง','restore')}</div><div class="notice">เก็บไฟล์สำรองในที่ปลอดภัย เพราะมีข้อมูลลูกค้าและการเงิน ก่อนกู้คืนระบบจะเก็บสำเนาปัจจุบันไว้ในฐานข้อมูลกลาง ดาวน์โหลดได้จากรายการสำเนาก่อนกู้คืน</div>`)}${panel('ประวัติการทำรายการ','เก็บผู้ทำ วันเวลา และการยกเลิก',S.audit.length?table(['เวลา','ผู้ทำ','การกระทำ','หมายเหตุ'],S.audit.slice(-100).reverse().map(a=>`<tr><td>${new Date(a.createdAt).toLocaleString('th-TH')}</td><td>${esc(a.by)}</td><td>${esc({customer:'เพิ่มลูกค้า',course:'เพิ่มคอร์ส',enroll:'ลงทะเบียน',entry:'บันทึกเงิน',movement:'บันทึกสต๊อก',product:'เพิ่มสินค้า',reverse:'กลับรายการ',pending:'ตรวจข้อมูล',purchase:'สั่งซื้อ',account:'เพิ่มบัญชี',debt:'ตั้งยอดหนี้',importHistory:'นำเข้าประวัติ',attendance:'เข้าร่วมคอร์ส',bom:'สูตรประกอบ',assemble:'ประกอบสินค้า',link:'ผูกการ์ด',restore:'กู้คืน',trello_push:'ส่ง Trello'}[a.action]||a.action)}</td><td class="wrap">${esc(a.note)}</td></tr>`)):empty('ยังไม่มีประวัติ','ประวัติจะเกิดเมื่อเริ่มทำรายการ'))}`;}
function bindFilters(){for(const k of ['search','from','to','project']){const input=$('#'+k);if(input)input.onchange=()=>{filters[k]=input.value;render();};}}
function simpleForm(title,action,content,extra={}){openModal(title,content,p=>act(action,{...p,...extra}),'บันทึกรายการ',action);}
function entryForm(type='income',extra={}){if(!S.accounts.length){toast('เพิ่มบัญชีเงินก่อนบันทึกรายการ');return accountForm();}const typeList=Object.entries(types).filter(([k])=>k!=='reversal'&&k!=='opening');openModal('บันทึกรับ–จ่าย',field('ประเภทรายการ','type','select',{options:typeList.map(([k,v])=>`<option value="${k}" ${k===type?'selected':''}>${v}</option>`).join('')})+field('บัญชีรับ / จ่าย','accountId','select',{options:options(S.accounts,x=>x.name+(x.scope==='personal'?' (ส่วนตัว)':''),extra.accountId)})+moneyField('จำนวนเงิน')+field('วันที่','date','date')+field('Invoice ที่รับชำระ (ถ้ามี)','invoiceId','select',{optional:true,options:options(S.documents.filter(d=>d.kind==='invoice'&&d.status==='issued'&&d.total-invoicePaidUI(d)>0),d=>d.number+' • '+d.customer.name+' ค้าง '+fmt(d.total-invoicePaidUI(d)),extra.invoiceId)})+field('อ้างอิงผู้ลงทะเบียน (เฉพาะรับค่าเรียน)','enrollmentId','select',{optional:true,options:options(S.enrollments,e=>name(S.customers,e.customerId)+' • '+name(S.courses,e.courseId)+' ค้าง '+fmt(e.price-paid(e.id)),extra.enrollmentId)})+field('อ้างอิงเงินเบิก (เคลียร์ / คืน)','advanceId','select',{optional:true,options:options(active().filter(e=>e.type==='advance'&&advanceLeft(e.id)>0),e=>e.note+' • เหลือ '+fmt(advanceLeft(e.id)),extra.advanceId)})+field('อ้างอิงใบสั่งซื้อ (รายจ่าย / เคลียร์)','purchaseId','select',{optional:true,options:options(S.purchases,p=>p.vendor+' • '+name(S.products,p.productId),extra.purchaseId)})+field('เจ้าหนี้ (เฉพาะคืนเงินต้น)','debtId','select',{optional:true,options:options(S.debts,x=>x.name)})+field('คอร์ส / โครงการ','project','text',{optional:true,full:true,value:extra.project||''})+field('ชื่อผู้ชำระสำหรับใบเสร็จ (กรณีไม่อ้างอิงลูกค้า)','receiptName','text',{optional:true,full:true})+field('รายละเอียด / ผู้เบิก / ผู้ขาย','note','textarea',{full:true,help:'ระบุเหตุผลและคู่ค้าให้ตรวจสอบย้อนหลังได้'}),async p=>{for(const k of ['enrollmentId','advanceId','purchaseId','debtId','invoiceId'])if(!p[k])delete p[k];const r=await act('entry',p);if(r.result)toast('บันทึกแล้ว · ตรวจสถานะส่ง Trello ได้จากรายการ');},'บันทึกรายการ','entry');}
function accountForm(){simpleForm('เพิ่มบัญชีเงิน','account',field('ชื่อบัญชี','name','text',{help:'เช่น เงินสดกิจการ หรือ ธนาคารกิจการ'})+field('เจ้าของเงิน','scope','select',{options:'<option value="business">กิจการ MY TECH</option><option value="personal">ส่วนตัวปิ๊ก</option>'}));}
function movementForm(extra={}){if(!S.products.length){toast('เพิ่มสินค้าก่อน');return dispatch('product');}openModal('รับ / เบิก / คืน / โอนสินค้า',field('ประเภท','type','select',{options:Object.entries(movementTypes).filter(([k])=>!k.startsWith('assembly')).map(([k,v])=>`<option value="${k}" ${k===extra.type?'selected':''}>${v}</option>`).join('')})+field('สินค้า','productId','select',{options:options(S.products,x=>x.sku+' • '+x.name,extra.productId)})+qtyField('จำนวน')+field('วันที่','date','date')+field('ที่เก็บต้นทาง / ที่รับเข้า','location','text',{value:extra.location||'',help:'ชื่อเดียวกันจะถือเป็นที่เก็บเดียวกัน'})+field('ที่เก็บปลายทาง (เฉพาะโอน)','destination','text',{optional:true})+moneyField('ต้นทุนรวมที่รับเข้า','amount',{optional:true,help:'ใช้เฉพาะรับเข้า/ปรับเพิ่ม หากอ้างอิงใบสั่งซื้อระบบคำนวณให้'})+field('ใบสั่งซื้อ (เฉพาะรับเข้า)','purchaseId','select',{optional:true,options:options(S.purchases.filter(p=>p.received<p.quantity),p=>p.vendor+' • '+name(S.products,p.productId)+' เหลือ '+qfmt(p.quantity-p.received),extra.purchaseId)})+field('ใบเบิกเดิม (เฉพาะคืน)','sourceId','select',{optional:true,options:options(S.movements.filter(m=>m.type==='issue'),m=>name(S.products,m.productId)+' • '+m.note)})+field('คอร์ส / โครงการ','project','text',{optional:true})+field('เหตุผล / รายละเอียด','note','textarea',{full:true}),p=>act('movement',{...p,amount:p.amount||'0'}));}
async function dispatch(command){if(await signatureUiDispatch(command))return;if(await trelloUiDispatch(command))return;if(await onlineDispatch(command))return;const [cmd,id,id2]=command.split(':');if(cmd==='close')return $('#modal').close();if(cmd==='menu')return $('.sidebar').classList.toggle('open');if(cmd==='go'){page=id;filters={};render();return;}
if(cmd==='logout'){location.href='/signout-with-chatgpt?return_to=%2F';return;}
if(cmd==='clearfilters'){filters={};render();return;}
if(['newdoc','convertquote','cancelDoc','invoicepay','company','adddocitem'].includes(cmd))return documentDispatch(cmd,id);if(cmd==='account')return accountForm();
if(cmd==='entry')return entryForm(id);
if(cmd==='opening')return simpleForm('ตั้งยอดยกมา · '+name(S.accounts,id),'entry',moneyField('ยอดเงินจริง ณ วันเริ่มต้น')+field('วันที่เริ่มต้น','date','date')+field('รายละเอียด','note','textarea',{full:true,value:'ยอดยกมา ณ วันเริ่มใช้ระบบ'}),{type:'opening',accountId:id});
if(cmd==='customer')return simpleForm('เพิ่มลูกค้า','customer',field('ชื่อลูกค้า','name')+field('โทรศัพท์','phone','tel',{optional:true})+field('LINE','line','text',{optional:true})+field('ที่อยู่','address','textarea',{optional:true,full:true})+field('เลขผู้เสียภาษี (ถ้ามี)','taxId','text',{optional:true})+field('หมายเหตุ','note','textarea',{optional:true,full:true}));
if(cmd==='course')return simpleForm('เพิ่มคอร์สเรียน','course',field('ชื่อคอร์ส','name')+field('รุ่น / รอบเรียน','cohort')+moneyField('ราคามาตรฐาน','price'));
if(cmd==='enroll')return simpleForm('ลงทะเบียนเรียน','enroll',field('ลูกค้า','customerId','select',{options:options(S.customers)})+field('คอร์ส','courseId','select',{options:options(S.courses,c=>c.name+' • '+c.cohort)})+moneyField('ราคาที่ตกลง (เว้นว่างใช้ราคามาตรฐาน)','price',{optional:true}));
if(cmd==='pay'){const en=S.enrollments.find(e=>e.id===id);return entryForm('income',{enrollmentId:id,project:name(S.courses,en.courseId)});}
if(cmd==='attend')return simpleForm('เข้าร่วมคอร์สเพิ่มเติม','attendance',field('คอร์สที่เข้าร่วม','courseId','select',{options:options(S.courses)})+field('วันที่เข้าร่วม','date','date'),{enrollmentId:id});
if(cmd==='settle'){const e=S.entries.find(e=>e.id===id);return entryForm('settlement',{advanceId:id,accountId:e.accountId,project:e.project});}
if(cmd==='purchasepay')return entryForm('expense',{purchaseId:id});
if(cmd==='reverse')return simpleForm('กลับรายการ · เก็บประวัติเดิม','reverse',field('วันที่กลับรายการ','date','date')+field('เหตุผลที่กลับรายการ','note','textarea',{full:true}),{id});
if(cmd==='product')return simpleForm('เพิ่มสินค้า / อุปกรณ์','product',field('รหัสสินค้า','sku')+field('ชื่อสินค้า','name')+field('ประเภท','kind','select',{options:'<option value="material">วัสดุ / อะไหล่ / สิ้นเปลือง</option><option value="tool">เครื่องมือใช้ซ้ำ</option><option value="finished">ของสำเร็จรูป / Simulator</option>'})+field('หน่วยนับ','unit','text',{help:'เช่น ตัว ชิ้น ชุด เมตร'})+field('จำนวนขั้นต่ำแจ้งเตือน','min','text',{value:'0',extra:'inputmode="decimal"'}));
if(cmd==='movement')return movementForm();
if(cmd==='receive'){const p=S.purchases.find(p=>p.id===id);return movementForm({type:'receive',productId:p.productId,purchaseId:id});}
if(cmd==='purchase')return simpleForm('เพิ่มใบสั่งซื้อ','purchase',field('ผู้ขาย','vendor')+field('สินค้า','productId','select',{options:options(S.products)})+qtyField('จำนวนที่สั่ง')+moneyField('ยอดซื้อรวม')+field('วันที่สั่ง','date','date')+field('รายละเอียด','note','textarea',{full:true}));
if(cmd==='debt')return simpleForm('เพิ่มยอดหนี้','debt',field('ชื่อเจ้าหนี้','name')+moneyField('ยอดหนี้ตั้งต้น')+field('หนี้ของ','scope','select',{options:'<option value="personal">ส่วนตัวปิ๊ก</option><option value="business">กิจการ</option>'})+field('วันครบกำหนด','due','date',{optional:true,value:''})+`<label class="checklabel full"><input type="checkbox" name="estimated" value="yes"> ยอดประมาณ ยังต้องตรวจยืนยัน</label>`+field('รายละเอียด','note','textarea',{full:true}));
if(cmd==='importHistory'){await act('importHistory',{});await reload();toast('นำเข้าประวัติรอตรวจสอบแล้ว ยังไม่ลงบัญชี');return;}
if(cmd==='review')return simpleForm('บันทึกผลตรวจข้อมูลเดิม','pending',field('สถานะ','status','select',{options:'<option value="reviewed">ตรวจแล้ว (ไม่ลงบัญชีอัตโนมัติ)</option><option value="pending">รอตรวจสอบ</option><option value="ignored">ไม่นำมาใช้</option>'})+field('ผลตรวจ / อ้างอิงรายการจริง','note','textarea',{full:true}),{id});
if(cmd==='staff')return openModal('เพิ่มบัญชีพนักงาน',field('ชื่อที่แสดง','name')+field('ชื่อผู้ใช้ภาษาอังกฤษ','username')+field('รหัสผ่านเริ่มต้น','password','password',{extra:'minlength="10" autocomplete="new-password"'}),p=>api('/api/user',p));
if(cmd==='bom'){openModal('เพิ่มสูตรประกอบ Simulator',field('ของสำเร็จรูป','productId','select',{options:options(S.products.filter(p=>p.kind==='finished'))})+`<div class="full"><label><span>ชิ้นส่วนต่อ 1 ชุด (เลือกได้หลายรายการ)</span></label><div id="parts">${partRow()}</div>${btn('เพิ่มชิ้นส่วน','addpart','small secondary')}</div>`,p=>{const parts=$$('#parts .bom-row').map(r=>({productId:r.querySelector('select').value,quantity:r.querySelector('input').value}));return act('bom',{productId:p.productId,parts});});return;}
if(cmd==='addpart'){$('#parts').insertAdjacentHTML('beforeend',partRow());return;}
if(cmd==='assemble')return simpleForm('ประกอบสินค้าจากสต๊อก','assemble',field('สูตรประกอบ','bomId','select',{options:options(S.boms,b=>name(S.products,b.productId),id)})+field('จำนวนชุด','count','number',{extra:'min="1" max="10000" step="1"'})+field('ที่เก็บชิ้นส่วนและสินค้าสำเร็จ','location')+field('วันที่','date','date')+field('โครงการ','project','text',{optional:true})+field('รายละเอียด','note','textarea',{full:true}));
if(cmd==='attach'){openModal('แนบหลักฐาน',field('รูปภาพหรือ PDF ไม่เกิน 10 MB','file','file',{full:true,extra:'accept="image/png,image/jpeg,image/webp,application/pdf"'}),async()=>{const f=$('#modal-form [name=file]').files[0];if(!f||f.size>10*1024*1024)throw new Error('ไฟล์ต้องไม่เกิน 10 MB');const b64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f);});await api('/api/attachment',{recordId:id,name:f.name,mime:f.type,base64:b64});});return;}
if(cmd==='detail'){const e=S.entries.find(x=>x.id===id);openModal('รายละเอียดรายการรับ–จ่าย',`<div class="full receipt"><strong>MY TECH · เอกสารรับ–จ่ายทั่วไป</strong><br>เลขรายการ ${esc(e.id)}<br>วันที่ ${thaiDate(e.date)}<br>${types[e.type]} ฿${fmt(e.amount)}<br>บัญชี ${esc(name(S.accounts,e.accountId))}<br>${esc(e.note)}<br>บันทึกโดย ${esc(e.by)}<br><span class="muted">ไม่ใช่ใบกำกับภาษี</span></div><div class="full"><h3>หลักฐานแนบ</h3>${S.attachmentList.filter(a=>a.recordId===id).map(a=>`<p><a href="/api/file/${esc(a.id)}" target="_blank" rel="noreferrer">${esc(a.name)}</a></p>`).join('')||'<p class="muted">ยังไม่มีไฟล์แนบ</p>'}</div>`,async()=>{} ,'ปิด');return;}
if(cmd==='link'){return trelloUiDispatch('trellorecord:'+id+':'+id2);const kind=id,recordId=id2;const existing=S.links.find(l=>l.kind===kind&&l.recordId===recordId);openModal('เชื่อมรายการกับ Trello',field('ลิงก์การ์ด Trello เดิม','url','url',{value:existing?.url||'',help:'ตัวอย่าง https://trello.com/c/รหัสการ์ด',full:true}),p=>act('link',{kind,id:recordId,url:p.url}));if(owner()&&S.trello.connected){const f=$('#modal-form');f.insertAdjacentHTML('beforeend',`<div class="notice info">หรือสร้าง/อัปเดตการ์ดในบอร์ดที่เลือก</div>${field('ลิสต์ปลายทาง','listId','select',{optional:true,options:options(S.trello.lists)})}${btn('สร้าง / อัปเดตการ์ดจริง','push:'+kind+':'+recordId,'secondary')}`);}return;}
if(cmd==='push'){const listId=$('#modal-form [name=listId]').value;if(!listId)throw new Error('เลือกลิสต์ปลายทาง');await api('/api/trello/push',{kind:id,recordId:id2,listId,note:'เชื่อมจากระบบบัญชี MY TECH'});$('#modal').close();await reload();toast('เชื่อมการ์ดสำเร็จ');return;}
if(cmd==='trelloconfig'){openModal('ตั้งค่าการเชื่อม Trello ของเว็บ',`<div class="notice info full">ต้องใช้ Key และ Token ของคุณเองสำหรับเว็บแอป ไม่ต้องส่งรหัสลับมาในแชต เริ่มตั้งค่าแอปได้ที่ <a href="https://trello.com/power-ups/admin" target="_blank" rel="noreferrer">Trello Power-Ups Admin ↗</a> ดูขั้นตอนในคู่มือที่มาพร้อมระบบ</div>`+field('API Key','key','password',{full:true,extra:'autocomplete="off"'})+field('Token','token','password',{full:true,extra:'autocomplete="off"'}),p=>api('/api/trello/config',p));return;}
if(cmd==='trellorefresh'){toast('กำลังอ่านข้อมูลจาก Trello…');await api('/api/trello/refresh',{});await reload();toast('รีเฟรช Trello สำเร็จ');return;}
if(cmd==='restore'){openModal('กู้คืนข้อมูลจากไฟล์สำรอง',`<div class="notice full">การกู้คืนจะแทนที่รายการทั้งหมด ระบบเก็บสำเนาก่อนกู้คืนไว้ให้อัตโนมัติ</div>`+field('ไฟล์สำรอง JSON','file','file',{full:true,extra:'accept=".json,application/json"'})+field('พิมพ์ “กู้คืนข้อมูล” เพื่อยืนยัน','confirm','text',{full:true}),async p=>{const file=$('#modal-form [name=file]').files[0];if(!file||file.size>10*1024*1024)throw new Error('ไฟล์เกิน 10 MB');await api('/api/restore',{confirm:p.confirm,backup:JSON.parse(await file.text())});},'ยืนยันกู้คืน');return;}
if(cmd==='csv'){const a=filtered(active());const rows=[['เลขรายการ','วันที่','ประเภท','บัญชี','ขอบเขต','จำนวนบาท','เงินเข้าออกบาท','โครงการ','รายละเอียด','ผู้บันทึก'],...a.map(e=>[e.id,e.date,types[e.type],name(S.accounts,e.accountId),S.accounts.find(a=>a.id===e.accountId)?.scope==='personal'?'ส่วนตัว':'กิจการ',(e.amount/100).toFixed(2),(e.cash/100).toFixed(2),e.project,e.note,e.by])];const csv='\ufeff'+rows.map(r=>r.map(c=>'"'+String(c??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const ael=document.createElement('a');ael.href=url;ael.download='MYTECH-'+nowDate()+'.csv';ael.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
if(cmd==='print')return window.print();
}
function partRow(){return `<div class="bom-row"><select aria-label="ชิ้นส่วน" required>${options(S.products.filter(p=>p.kind!=='tool'))}</select><input aria-label="จำนวนต่อชุด" placeholder="จำนวน" inputmode="decimal" required><button type="button" class="ghost remove-part" aria-label="ลบชิ้นส่วน">✕</button></div>`;}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-page]');if(nav){page=nav.dataset.page;filters={};render();return;}const remove=e.target.closest('.remove-part');if(remove){remove.closest('.bom-row').remove();return;}const removeDoc=e.target.closest('.remove-docitem');if(removeDoc){removeDoc.closest('.docitem-row').remove();return;}const b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();if(busy&&b.dataset.act!=='close')return;try{await dispatch(b.dataset.act);}catch(err){const errEl=$('#modal[open] .error');if(errEl)errEl.textContent=err.message;else toast(err.message);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
async function init(){try{const r=await api('/api/session');U=r.user;page=requestedPage(window.location.search)||page;if(U)await reload();else authView(r.setup);}catch(e){$('#app').innerHTML=`<div class="loading">เปิดระบบไม่สำเร็จ: ${esc(e.message)}</div>`;}}
function invoicePaidUI(d){return active().filter(e=>d.enrollmentId?e.enrollmentId===d.enrollmentId:e.invoiceId===d.id).reduce((a,e)=>a+e.amount,0);}
function documentsView(){return `<div class="notice info">ใบเสนอราคาไม่สร้างลูกหนี้ Invoice สร้างยอดค้างรับ แต่ไม่เพิ่มรายรับจนกว่าจะบันทึกชำระ สำหรับคอร์สเรียนให้เลือกการลงทะเบียนเดิมเพื่อไม่รวมลูกหนี้ซ้ำ</div>${panel('ใบเสนอราคาและใบแจ้งหนี้','ออกเอกสารทั่วไป · พิมพ์ PDF และดาวน์โหลดภาพได้',S.documents.length?table(['เลขที่ / ประเภท','ลูกค้า','วันที่ / กำหนด','ยอดรวม / คงเหลือ','สถานะ','จัดการ'],S.documents.slice().reverse().map(d=>`<tr><td><strong>${esc(d.number)}</strong><br><span class="muted">${d.kind==='quote'?'ใบเสนอราคา':'Invoice / ใบแจ้งหนี้'}</span></td><td>${esc(d.customer.name)}</td><td>${thaiDate(d.date)}<br><span class="muted">${d.due?thaiDate(d.due):'—'}</span></td><td class="num">฿${fmt(d.total)}${d.kind==='invoice'?'<br><span class="muted">ค้าง '+fmt(d.total-invoicePaidUI(d))+'</span>':''}</td><td>${badge(d.status==='cancelled'?'ยกเลิก':d.kind==='quote'?'ออกแล้ว':invoicePaidUI(d)===d.total?'รับครบ':d.due&&d.due<nowDate()?'เกินกำหนด':'รอชำระ',d.status==='cancelled'?'gray':d.kind==='invoice'&&invoicePaidUI(d)<d.total?'warn':'')}</td><td><div class="actions"><a href="/api/document?id=${esc(d.id)}" target="_blank" rel="noreferrer"><button class="small secondary">เปิด / พิมพ์</button></a>${btn('Trello','trellorecord:document:'+d.id,'small secondary')}${btn('แนบไฟล์','attach:'+d.id,'small secondary')}${trelloRecordStatus('document',d.id)}${d.status==='issued'?(d.kind==='quote'?btn('แปลงเป็น Invoice','convertquote:'+d.id,'small secondary'):btn('รับชำระ','invoicepay:'+d.id,'small secondary')):''}${d.status==='issued'?btn('ยกเลิก','cancelDoc:'+d.id,'small danger'):''}</div></td></tr>`)):empty('ยังไม่มีเอกสาร','เพิ่มลูกค้าและข้อมูลกิจการ แล้วเริ่มออกใบเสนอราคาหรือ Invoice'))}`;}
function docItemRow(x={}){return `<div class="docitem-row"><label><span>รายการสินค้า / บริการ *</span><input class="description" required maxlength="300" value="${esc(x.description||'')}"></label><label><span>จำนวน *</span><input class="quantity" required inputmode="decimal" value="${esc(x.quantity?x.quantity/1000:'1')}"></label><label><span>ราคาต่อหน่วย *</span><input class="price" required inputmode="decimal" value="${esc(x.unitPrice!==undefined?(x.unitPrice/100).toFixed(2):'')}"></label><button type="button" class="ghost remove-docitem" aria-label="ลบรายการ">✕</button></div>`;}
function documentDispatch(cmd,id){
if(cmd==='adddocitem'){$('#document-items').insertAdjacentHTML('beforeend',docItemRow());return;}
if(cmd==='company')return openModal('ข้อมูลกิจการสำหรับเอกสาร',field('ชื่อกิจการ','name','text',{value:S.company.name,full:true})+field('ที่อยู่','address','textarea',{value:S.company.address,optional:true,full:true})+field('เลขผู้เสียภาษี (ถ้ามี)','taxId','text',{value:S.company.taxId,optional:true})+field('โทรศัพท์','phone','tel',{value:S.company.phone,optional:true})+field('ข้อมูลรับชำระ / บัญชีธนาคาร','paymentInfo','textarea',{value:S.company.paymentInfo,optional:true,full:true}),p=>act('company',p));
if(cmd==='cancelDoc')return simpleForm('ยกเลิกเอกสาร · เก็บประวัติ','cancelDocument',field('เหตุผลยกเลิก','note','textarea',{full:true}),{id});
if(cmd==='invoicepay'){const d=S.documents.find(d=>d.id===id);return entryForm('income',{invoiceId:id,enrollmentId:d.enrollmentId||'',project:d.number});}
const src=cmd==='convertquote'?S.documents.find(d=>d.id===id):null,kind=src?'invoice':id;
return openModal(kind==='quote'?'ออกใบเสนอราคา':'ออก Invoice / ใบแจ้งหนี้',field('ลูกค้า','customerId','select',{options:options(S.customers,x=>x.name,src?.customerId)})+field('วันที่เอกสาร','date','date')+field(kind==='quote'?'ยืนราคาถึง':'กำหนดชำระ','due','date',{optional:true,value:''})+field('การลงทะเบียนคอร์สเดิม (ถ้ามี)','enrollmentId','select',{optional:true,options:options(S.enrollments,e=>name(S.customers,e.customerId)+' • '+name(S.courses,e.courseId)+' '+fmt(e.price),src?.enrollmentId),help:'ยอดเอกสารต้องตรงกับค่าคอร์ส เพื่อไม่สร้างลูกหนี้ซ้ำ'})+`<div class="full"><div id="document-items">${src?src.items.map(docItemRow).join(''):docItemRow()}</div>${btn('เพิ่มรายการ','adddocitem','small secondary')}</div>`+moneyField('ส่วนลดรวม','discount',{value:src?(src.discount/100).toFixed(2):'0'})+field('หมายเหตุ / เงื่อนไข','note','textarea',{optional:true,full:true,value:src?.note||'',help:'เอกสารทั่วไป ไม่ใช่ใบกำกับภาษี'}),p=>{const items=$$('#document-items .docitem-row').map(row=>({description:row.querySelector('.description').value,quantity:row.querySelector('.quantity').value,price:row.querySelector('.price').value}));return act('document',{...p,kind,items,sourceQuoteId:src?.id||null});},'ออกเอกสาร','document');
}
